package com.soumyajit.gradlemc.investigation.storage;
import com.google.gson.*;import com.soumyajit.gradlemc.investigation.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.*;
public final class InvestigationIndexCodec { public static final int MAX_BYTES=128*1024; public byte[] encode(InvestigationIndex value){JsonObject o=new JsonObject();o.addProperty("schemaVersion",value.schemaVersion());JsonArray a=new JsonArray();for(var e:value.entries()){JsonObject x=new JsonObject();x.addProperty("id",e.id().value());x.addProperty("profileId",e.profileId().value());x.addProperty("state",e.state().name());x.addProperty("createdAt",e.createdAt().toString());x.addProperty("endedAt",e.endedAt()==null?null:e.endedAt().toString());x.addProperty("revision",e.revision());a.add(x);}o.add("entries",a);return(new GsonBuilder().disableHtmlEscaping().create().toJson(o)+"\n").getBytes(StandardCharsets.UTF_8);} public InvestigationIndex decode(byte[] bytes)throws IOException{if(bytes==null||bytes.length>MAX_BYTES)throw new IOException("Index exceeds safe size limit");try{JsonObject o=JsonParser.parseString(new String(bytes,StandardCharsets.UTF_8)).getAsJsonObject();JsonArray a=o.getAsJsonArray("entries");if(a==null||a.size()>InvestigationIndex.MAX_SESSIONS)throw new IllegalArgumentException("Invalid index entries");List<InvestigationIndexEntry>out=new ArrayList<>();for(JsonElement x:a){JsonObject e=x.getAsJsonObject();out.add(new InvestigationIndexEntry(new InvestigationId(s(e,"id")),new InvestigationProfileId(s(e,"profileId")),InvestigationState.valueOf(s(e,"state")),Instant.parse(s(e,"createdAt")),optional(e,"endedAt"),Long.parseLong(s(e,"revision"))));}return new InvestigationIndex(Integer.parseInt(s(o,"schemaVersion")),out);}catch(RuntimeException e){throw new IOException("Malformed or unsupported investigation index",e);}}private static String s(JsonObject o,String n){JsonElement e=o.get(n);if(e==null||e.isJsonNull())throw new IllegalArgumentException("Missing "+n);return e.getAsString();}private static Instant optional(JsonObject o,String n){JsonElement e=o.get(n);return e==null||e.isJsonNull()?null:Instant.parse(e.getAsString());}}
